CREATE FUNCTION public.guard_fuel_credit_restoration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE covered numeric; restored numeric; BEGIN IF NEW.credit_used < OLD.credit_used THEN SELECT COALESCE(sum(paid),0) INTO covered FROM public.fuel_card_invoices WHERE account_id=OLD.id; SELECT COALESCE(sum(new_limit-old_limit),0) INTO restored FROM public.fuel_card_limit_events WHERE account_id=OLD.id AND reason LIKE 'Paiement facture %'; IF covered-restored < OLD.credit_used-NEW.credit_used THEN RAISE EXCEPTION 'Reconstitution sans facture réglée interdite'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER fuel_credit_guard BEFORE UPDATE OF credit_used ON public.fuel_card_accounts FOR EACH ROW EXECUTE FUNCTION public.guard_fuel_credit_restoration();
CREATE TRIGGER fuel_transactions_immutable BEFORE UPDATE OR DELETE ON public.fuel_card_transactions FOR EACH ROW EXECUTE FUNCTION public.audit_logs_immutable();
CREATE TRIGGER fuel_limit_events_immutable BEFORE UPDATE OR DELETE ON public.fuel_card_limit_events FOR EACH ROW EXECUTE FUNCTION public.audit_logs_immutable();
CREATE TRIGGER fuel_alerts_immutable BEFORE UPDATE OR DELETE ON public.fuel_card_alerts FOR EACH ROW EXECUTE FUNCTION public.audit_logs_immutable();